class ProgressionTrack { int experience=0,level=1,skillPoints=0; final Set<String> unlockedPerks={}; int get experienceToNext=>100+level*45; void grantExperience(int amount){experience+=amount;while(experience>=experienceToNext){experience-=experienceToNext;level++;skillPoints++;}} bool unlock(String id,{int cost=1}){if(skillPoints<cost||unlockedPerks.contains(id))return false;skillPoints-=cost;unlockedPerks.add(id);return true;} Map<String,dynamic> toJson()=>{'experience':experience,'level':level,'skillPoints':skillPoints,'unlockedPerks':unlockedPerks.toList()}; void loadJson(dynamic raw){if(raw is! Map)return;experience=(raw['experience'] as num?)?.toInt()??0;level=(raw['level'] as num?)?.toInt()??1;skillPoints=(raw['skillPoints'] as num?)?.toInt()??0;unlockedPerks..clear()..addAll((raw['unlockedPerks'] is List?(raw['unlockedPerks'] as List).whereType<String>():const <String>[]));} }
